const fs = require('fs');
const path = require('path');

const TESTBED_DIR = '/workspace/testbed';
const sender = 'priya.it.lead';
const recipient = 'ethan.it.specialist';
const subject = 'Re: High Priority: Onboarding Equipment Setup Needed - Follow-Up';
const content = \`Hello Ethan,

This is to confirm that the onboarding equipment setup for the new contractor has been tracked and scheduled for Tuesday, September 9, 2026.

Please ensure the following tasks are completed before start of business on that day:

1. Provision a standard Windows laptop
2. Configure VPN access
3. Set up email account

A calendar event has been created to track this request. Please prioritize accordingly and let me know if you anticipate any issues.

Best regards,
Priya\`;

// Build the .eml content
const eml = [
  'From: ' + sender + '@company.com',
  'To: ' + recipient + '@company.com',
  'Subject: ' + subject,
  'MIME-Version: 1.0',
  'Content-Type: text/plain; charset=\"utf-8\"',
  '',
  content
].join('\r\n');

// Save to both sender and recipient folders
[sender, recipient].forEach(folder => {
  const dir = path.join(TESTBED_DIR, 'emails', folder);
  fs.mkdirSync(dir, { recursive: true });
  const filePath = path.join(dir, subject + '.eml');
  fs.writeFileSync(filePath, eml);
  console.log('Saved:', filePath);
});

console.log('\n--- Email Content ---');
console.log(eml);
"
